-- Leonida Records — update to v2.5
-- English becomes the main language (Spanish second; Portuguese and French removed from the site)
-- and the vehicle catalogue is added. Run once in Supabase → SQL Editor. Safe to run more than once.
begin;

-- 1. Localized values fall back to English first, then Spanish
create or replace function public.lr_pick(v jsonb, lang text)
returns text language sql immutable as $$
  select coalesce(nullif(v ->> lang, ''), nullif(v ->> 'en', ''), nullif(v ->> 'es', ''), '');
$$;

-- 2. Titles/names may be written in English or Spanish (before: Spanish was mandatory)
do $$
declare r record;
begin
  for r in
    select conrelid::regclass as tbl, conname from pg_constraint
    where contype = 'c'
      and conrelid in ('public.entities'::regclass, 'public.facts'::regclass, 'public.categories'::regclass, 'public.articles'::regclass, 'public.timeline_events'::regclass)
      and pg_get_constraintdef(oid) like '%->> ''es''%'
  loop
    execute format('alter table %s drop constraint %I', r.tbl, r.conname);
  end loop;
end $$;
alter table public.entities        add constraint entities_title_check        check (public.lr_is_localized(title) and (length(coalesce(title ->> 'en', '')) > 0 or length(coalesce(title ->> 'es', '')) > 0));
alter table public.facts           add constraint facts_title_check           check (public.lr_is_localized(title) and (length(coalesce(title ->> 'en', '')) > 0 or length(coalesce(title ->> 'es', '')) > 0));
alter table public.categories      add constraint categories_name_check       check (public.lr_is_localized(name) and (length(coalesce(name ->> 'en', '')) > 0 or length(coalesce(name ->> 'es', '')) > 0));
alter table public.articles        add constraint articles_title_check        check (public.lr_is_localized(title) and (length(coalesce(title ->> 'en', '')) > 0 or length(coalesce(title ->> 'es', '')) > 0));
alter table public.timeline_events add constraint timeline_events_title_check check (public.lr_is_localized(title) and (length(coalesce(title ->> 'en', '')) > 0 or length(coalesce(title ->> 'es', '')) > 0));

-- 3. Activity log labels prefer English
create or replace function public.log_activity()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  rec jsonb := to_jsonb(coalesce(new, old));
  lbl text;
  who text;
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  lbl := coalesce(rec -> 'title' ->> 'en', rec -> 'title' ->> 'es', rec -> 'name' ->> 'en', rec -> 'name' ->> 'es', rec ->> 'name', rec ->> 'alt_text', rec ->> 'storage_path', rec ->> 'key');
  select coalesce(display_name, email) into who from public.profiles where id = auth.uid();
  insert into public.activity_log (actor_id, actor_name, action, table_name, record_id, label)
  values (
    auth.uid(), who,
    case
      when tg_op = 'UPDATE' and (rec ? 'published')
           and (to_jsonb(old) ->> 'published') is distinct from (to_jsonb(new) ->> 'published')
        then case when (to_jsonb(new) ->> 'published')::boolean then 'publish' else 'unpublish' end
      else lower(tg_op)
    end,
    tg_table_name,
    case when rec ? 'id' and jsonb_typeof(rec -> 'id') = 'string' then (rec ->> 'id')::uuid else null end,
    left(lbl, 200)
  );
  return coalesce(new, old);
end;
$$;

-- 4. Search defaults to English
drop function if exists public.search_archive(text, text, integer);
create or replace function public.search_archive(q text, lang text default 'en', max_results integer default 40)
returns table (kind text, id uuid, type text, slug text, title text, excerpt text, status text, image text, rank integer)
language sql stable security invoker set search_path = public as $$
  with term as (select '%' || public.lr_fold(trim(q)) || '%' as t)
  select * from (
    select 'entity'::text, e.id, e.type, e.slug,
           public.lr_pick(e.title, lang), public.lr_pick(e.short_description, lang),
           e.status, e.hero_image,
           case
             when public.lr_fold(public.lr_all_text(e.title)) like (select t from term) then 3
             when public.lr_fold(array_to_string(e.tags, ' ')) like (select t from term) then 2
             else 1
           end
    from public.entities e
    where e.published
      and (   public.lr_fold(public.lr_all_text(e.title)) like (select t from term)
           or public.lr_fold(public.lr_all_text(e.short_description)) like (select t from term)
           or public.lr_fold(array_to_string(e.tags, ' ')) like (select t from term)
           or e.slug like (select t from term))
    union all
    select 'article'::text, a.id, 'news'::text, a.slug,
           public.lr_pick(a.title, lang), public.lr_pick(a.excerpt, lang),
           a.evidence, a.cover_image,
           case
             when public.lr_fold(public.lr_all_text(a.title)) like (select t from term) then 3
             when public.lr_fold(array_to_string(a.tags, ' ')) like (select t from term) then 2
             else 1
           end
    from public.articles a
    where a.published and a.published_at <= now()
      and (   public.lr_fold(public.lr_all_text(a.title)) like (select t from term)
           or public.lr_fold(public.lr_all_text(a.excerpt)) like (select t from term)
           or public.lr_fold(array_to_string(a.tags, ' ')) like (select t from term))
  ) r (kind, id, type, slug, title, excerpt, status, image, rank)
  where length(trim(coalesce(q, ''))) >= 2
  order by rank desc, title
  limit least(greatest(max_results, 1), 100);
$$;
grant execute on function public.search_archive(text, text, integer) to anon, authenticated;

-- 5. Correct name of the Ultimate Edition buggy (it was listed as "Dominator FX")
update public.entities
set slug = '67-vapid-dominator-buggy',
    title = '{"en": "’67 Vapid Dominator Buggy"}'::jsonb,
    short_description = short_description || '{"es":"Un Vapid Dominator de 1967 convertido en buggy todoterreno, incluido con el garaje Paradise Garage en la Ultimate Edition.","en":"A 1967 Vapid Dominator rebuilt as an off-road buggy, included with the Paradise Garage in the Ultimate Edition."}'::jsonb,
    description = description || '{"es":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar lo presenta como un «monstruo del Mud Club» con gran manejo fuera del asfalto, pensado para los bosques de Mount Kalaga y más allá."}]},{"type":"paragraph","content":[{"type":"text","text":"Llega junto al Paradise Garage como parte de la Ultimate Edition."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rockstar describes it as a Mud Club monster with impressive off-road handling for the backwoods of Mount Kalaga and beyond."}]},{"type":"paragraph","content":[{"type":"text","text":"It comes with the Paradise Garage as part of the Ultimate Edition."}]}]}}'::jsonb
where type = 'vehicles' and slug = '67-vapid-dominator-fx';

